// Normalize the raw Meta WhatsApp event into the NEXUS ingest contract.
const entry = $input.first().json.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const waMessage = value?.messages?.[0];

if (!waMessage) {
  return [{ json: { type: 'unsupported', reason: 'no message payload' } }];
}

const phone = waMessage.from || value?.contacts?.[0]?.wa_id || '';
const name = value?.contacts?.[0]?.profile?.name || null;
const textBody = waMessage.text?.body ?? '';
const isText = waMessage.type === 'text' && textBody.length > 0;

const normalized = {
  event: 'message',
  from: { phone, name },
  message: {
    id: waMessage.id,
    type: waMessage.type,
    text: { body: textBody },
    timestamp: waMessage.timestamp
  },
  phoneNumberId: value?.metadata?.phone_number_id || null
};

if (isText) {
  return [{ json: { type: 'text', payload: normalized } }];
}
return [{ json: { type: 'unsupported', payload: normalized } }];

// Route: text messages go to the AI agent; everything else gets a fallback.
const item = $input.first().json;
if (item.type === 'text') {
  return [{ json: item }];
}
return [{ json: { type: 'unsupported', fallback: 'Thanks for your message. This message type is not supported for automatic analysis yet. Please forward the text here, or visit the NEXUS portal to submit it.' } }];

// Parse the agent's structured output and attach the bot reply text.
const agentText = $input.first().json.output ?? $input.first().json.text ?? '';
const parsed = (() => {
  const cleaned = agentText.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1) return null;
  try { return JSON.parse(cleaned.slice(start, end + 1)); } catch { return null; }
})();

const ingest = $('NEXUS Ingest (create conversation + deterministic analysis)').first().json;
const message = $('Normalize WhatsApp Message').first().json.payload.message;

const fallback = 'Your message has been analyzed and recorded. A response is being prepared — please stay on this chat.';

return [{
  json: {
    conversationId: ingest.conversationId,
    result: parsed ?? {
      riskLevel: ingest.analysis?.riskLevel ?? 'UNKNOWN',
      score: ingest.analysis?.score ?? null,
      confidence: null,
      summary: ingest.analysis?.summary ?? 'Analysis completed.',
      evidence: [],
      safeNextSteps: [],
      limitations: ['The AI explanation could not be generated.']
    },
    replyText: buildReply(parsed, ingest.analysis),
    workflowId: $workflow.id,
    executionId: $execution.id
  }
}];

function buildReply(ai, analysis) {
  const risk = ai?.riskLevel ?? analysis?.riskLevel ?? 'UNKNOWN';
  const summary = ai?.summary ?? analysis?.summary ?? '';
  if (risk === 'HIGH' || risk === 'CRITICAL') {
    return '⚠️ This message shows strong signs of fraud. ' + summary + ' Do NOT click links, share OTPs, or send money. Report to the national fraud helpline (1930 in India) if needed.';
  }
  if (risk === 'MEDIUM') {
    return '⚠️ This message has some suspicious signs. ' + summary + ' Please verify before acting and avoid sharing personal details.';
  }
  return '✅ This message looks safe, but stay alert. ' + summary;
}
